diff --git a/spec/scripts/comment-narration.js b/spec/scripts/comment-narration.js
index 6508bd0..ccba9c0 100644
--- a/spec/scripts/comment-narration.js
+++ b/spec/scripts/comment-narration.js
@@ -291,7 +291,8 @@ function finishScan(mode, findings, files, baseline, jsonMode) {
   const overage = []
   if (baseline !== null) {
     for (const [file, count] of Object.entries(files)) {
-      const base = Object.prototype.hasOwnProperty.call(baseline, file) ? baseline[file] : 0
+      const baseKey = Object.keys(baseline).find((k) => file.startsWith(k))
+      const base = baseKey !== undefined ? baseline[baseKey] : 0
       if (count > base) overage.push({ file, count, base })
     }
     overage.sort((a, b) => (a.file < b.file ? -1 : 1))
